        </Section>
      ) : null}

      <Section title="Advanced">
        <Pressable onPress={() => setShowManual((v) => !v)} hitSlop={6}>
          <Text style={{ color: theme.colors.accent, fontWeight: "500" }}>
            {showManual ? "Hide manual setup" : "Set up manually (git remote URL)"}
