        let spawned = Command::new(&self.shared.git_path)
            .arg(service)
            .arg(&self.shared.repo_path)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .kill_on_drop(true)
            .spawn();
