+
+fn normalize_host_for_compare(value: &str) -> String {
+    let trimmed = value.trim().trim_start_matches('[').trim_end_matches(']');
+    if let Some((host, port)) = trimmed.rsplit_once(':') {
+        if port.chars().all(|c| c.is_ascii_digit()) && !host.contains(':') {
