+
+fn tcp_target_from_url_authority(rest: &str, default_port: u16) -> Option<TcpTarget> {
+    let authority = rest.split('/').next()?.split('?').next()?.split('#').next()?;
+    let host_port = authority.rsplit('@').next().unwrap_or(authority);
+    parse_host_port(host_port, default_port)
+}
+
+fn tcp_target_from_scp_like(value: &str) -> Option<TcpTarget> {
+    if value.contains("://") {
+        return None;
+    }
+    let before_colon = value.split(':').next()?;
+    if before_colon.contains('/') {
+        return None;
+    }
+    let host = before_colon.rsplit('@').next().unwrap_or(before_colon).trim();
+    if host.is_empty() {
+        None
+    } else {
+        Some(TcpTarget {
+            host: host.to_string(),
+            port: 22,
+        })
+    }
+}
+
+fn parse_host_port(value: &str, default_port: u16) -> Option<TcpTarget> {
+    let trimmed = value.trim();
+    if trimmed.is_empty() {
+        return None;
+    }
+    if let Some(end) = trimmed.strip_prefix('[').and_then(|v| v.find(']').map(|idx| idx + 1)) {
+        let host = &trimmed[1..end];
+        let port = trimmed
+            .get(end + 1..)
+            .and_then(|suffix| suffix.strip_prefix(':'))
+            .and_then(|port| port.parse().ok())
+            .unwrap_or(default_port);
+        return Some(TcpTarget {
+            host: host.to_string(),
+            port,
+        });
+    }
+    if let Some((host, port)) = trimmed.rsplit_once(':') {
+        if !host.contains(':') {
+            return Some(TcpTarget {
+                host: host.to_string(),
+                port: port.parse().unwrap_or(default_port),
+            });
+        }
+    }
+    Some(TcpTarget {
+        host: trimmed.to_string(),
+        port: default_port,
+    })
